-- «УНИК», часть 1 из 7. Выполняйте части по порядку: 1, 2, 3… Пока не выполнена последняя, игра видна только админам.
alter table public.games drop constraint if exists games_item_check;
alter table public.games add constraint games_item_check check (item in ('cassette','cd','floppy','handheld','cards'));
alter table public.games add column if not exists shot_img text check (shot_img is null or char_length(shot_img) <= 150000);
alter table public.games add column if not exists has_shot boolean generated always as (shot_img is not null) stored;
insert into public.games (id, title, tags, description, changes, version, author_name, item, cover, cover_img, shot_img, tint, bg, access, sort, play_kind, file_html)
values ('unik', 'УНИК', '["Карты","Кооп","Онлайн"]'::jsonb, $cpx$Яркая карточная игра в духе классики: сбрасывайте карты по цвету или числу, кидайте соперникам +2 и +4, меняйте направление и первым избавьтесь от всех карт. Играйте против ботов без интернета, в кооп «люди против ботов» или онлайн с друзьями — до 4 игроков по коду или QR. Игра — один HTML-файл: её можно скачать или запустить прямо в браузере кнопкой «Играть».$cpx$, '', '1.0', 'Makama', 'cards', 'img:c2f39071e1b0', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', '{"h":265,"s":0.85}'::jsonb, 'auto', 'staff', 9, 'auto', '')
on conflict (id) do update set
  title = excluded.title, tags = excluded.tags, description = excluded.description, version = excluded.version,
  author_name = excluded.author_name, item = excluded.item, cover = excluded.cover, cover_img = excluded.cover_img, shot_img = excluded.shot_img,
  tint = excluded.tint, access = 'staff', file_html = '', dl_off = false, updated_at = now();